head.script:
scwin.gVar = {
    "bReady" : false,
    // 행1, 행2 는 같은 데이터값 (같은 값으로의 선택 변경 케이스)
    "arrData" : [
        { "label" : "data_A", "value" : "1" },
        { "label" : "data_B", "value" : "2" },
        { "label" : "data_B", "value" : "3" },
    ],
}



// 테스트 설명, 유효성 값 설정
//  - ref 바인딩 DataCollection 의 데이터 선택 변경 축을 담당한다. ref=data:dlt_ref.label 로 고정한다.
//  - 발생 조건(포커스 해제 / setValue / 값 변경 없음 / Enter) 과 info 파라미터는 secret_E_onviewchange_1.xml, 이벤트 발생 순서는 secret_E_onviewchange_3.xml 에서 검증한다.
//  - secret 은 입력창이 마스킹되어 화면으로 값 변경을 볼 수 없으므로, 선택 후 target1 값을 함께 출력해 데이터 선택이 실제로 반영되었음을 전제로 남긴다.
scwin.tData = {
    "description" : "[secret > E > onviewchange]<br/>Secret 컴포넌트에서 사용자의 조작에 의해 입력값이 변경된 후 포커스가 해제될때 발생합니다.",
    "validation" : [
        "ref 속성으로 DataCollection 을 바인딩 한 경우 데이터 선택이 변경되어도 onviewchange 이벤트는 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 생성 중 헬퍼의 초기값 설정으로 발생하는 이벤트는 출력하지 않음
    scwin.gVar["bReady"] = false;

    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 ref=data:dlt_ref.label 로 고정 설정\ndlt_ref 데이터 : 행0 data_A / 행1 data_B / 행2 data_B (행1, 행2 는 같은 값)\nTarget 재생성 시 dlt_ref 는 위 데이터로 초기화되고 미선택 상태가 됩니다\n[절차] 행0 선택 -> 행1 선택 -> 행2 선택 순서로 클릭\n[확인] 각 선택 줄의 target1 값이 바뀌는데도 onviewchange 발생 줄이 나타나지 않는지 (입력창은 마스킹되어 화면으로는 값을 볼 수 없습니다)"', '', 'label1');

    // 바인딩 데이터 초기화 (미선택 상태)
    dlt_ref.setJSON(JSON.parse(JSON.stringify(scwin.gVar["arrData"])));
    dlt_ref.setRowPosition(-1);

    let properties = {
        ref : "data:dlt_ref.label",
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onviewchange"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, eList);

    // 헬퍼가 넣은 초기값을 지워 DataList 바인딩 결과(미선택 = 빈값)만 입력창에 남긴다
    target1.setValue("");

    scwin.gVar["bReady"] = true;
}



// DataList 선택 변경 (validation 1 발동 수단)
scwin.fn_selectRow = function (nRow) {
    wf_body_bottom.getObj("scwin").setReturnValue("DataList 행" + nRow + " 선택 (label : " + dlt_ref.getCellData(nRow, "label") + ")");

    dlt_ref.setRowPosition(nRow);

    wf_body_bottom.getObj("scwin").setReturnValue("선택 후 target1 값 : " + target1.getValue());
}



scwin.btn_selectRow0_onclick = function (e) {
    scwin.fn_selectRow(0);
}



scwin.btn_selectRow1_onclick = function (e) {
    scwin.fn_selectRow(1);
}



scwin.btn_selectRow2_onclick = function (e) {
    scwin.fn_selectRow(2);
}



// validation 1 판정 출력 (발생하지 않아야 하며, 발생 시 info 속성으로 원인을 확인)
scwin.target1_onviewchange = function (info) {
    if (!scwin.gVar["bReady"])
        return;

    wf_body_bottom.getObj("scwin").setReturnValue("▶ onviewchange 발생");
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
}
